original_sql:
SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.bond_type = '#' THEN b.molecule_id END) / COUNT(DISTINCT m.molecule_id) AS percent
FROM molecule m
LEFT JOIN bond b ON m.molecule_id = b.molecule_id;

