original_sql:
SELECT (COUNT(CASE WHEN strftime('%Y', Date) = '2010' THEN 1 END) * 100.0 / COUNT(*)) - (COUNT(CASE WHEN strftime('%Y', Date) = '2011' THEN 1 END) * 100.0 / COUNT(*)) AS percentage_difference
FROM badges
WHERE Name = 'Students';

SELECT
  (SELECT COUNT(*) FROM comments JOIN posts ON comments.PostId = posts.Id WHERE posts.Title = 'Clustering 1D data') AS comments_count,
  (SELECT COUNT(*) FROM posts AS answers JOIN posts AS question ON answers.ParentId = question.Id WHERE question.Title = 'Clustering 1D data' AND answers.PostTypeId = 2) AS answers_count;

SELECT ROUND(AVG(CASE WHEN Admission = '+' THEN 100.0 ELSE 0 END), 2) AS inpatient_percentage
FROM Patient
WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';

