original_sql:
SELECT 1.0 * COUNT(CASE WHEN Laboratory.GOT >= 60 AND Patient.Diagnosis = 'SLE' THEN Laboratory.ID END) / NULLIF(COUNT(CASE WHEN Laboratory.GOT >= 60 THEN Laboratory.ID END), 0) AS percentage
FROM Laboratory
JOIN Patient ON Laboratory.ID = Patient.ID;

